-- ========================================================
-- JOSE RIZAL UNIVERSITY (JRU) ALUMNI TRACKER DATABASE SCHEMA
-- Target: PostgreSQL (Render)
-- ========================================================

DROP TABLE IF EXISTS alumni;
DROP TABLE IF EXISTS programs;
DROP TABLE IF EXISTS colleges;

CREATE TABLE IF NOT EXISTS colleges (
  college_key VARCHAR(10) PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  short_name VARCHAR(20) NOT NULL,
  badge_color_gradient VARCHAR(100) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS programs (
  program_id SERIAL PRIMARY KEY,
  college_key VARCHAR(10) NOT NULL REFERENCES colleges(college_key) ON DELETE CASCADE,
  code VARCHAR(20) NOT NULL,
  name VARCHAR(150) NOT NULL,
  major VARCHAR(150) DEFAULT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS alumni (
  id VARCHAR(50) PRIMARY KEY,
  student_id VARCHAR(20) NOT NULL UNIQUE,
  full_name VARCHAR(150) NOT NULL,
  batch_year INT NOT NULL,
  college_key VARCHAR(10) NOT NULL REFERENCES colleges(college_key) ON DELETE CASCADE,
  program_name VARCHAR(200) NOT NULL,
  major VARCHAR(150) DEFAULT NULL,
  motto TEXT NOT NULL,
  honor VARCHAR(100) DEFAULT 'Graduate',
  academic_highlights TEXT DEFAULT NULL,
  avatar_url TEXT DEFAULT NULL,
  verified BOOLEAN DEFAULT TRUE,
  email VARCHAR(150) DEFAULT NULL,
  linkedin VARCHAR(255) DEFAULT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_student_id ON alumni (student_id);
CREATE INDEX IF NOT EXISTS idx_batch_year ON alumni (batch_year);
CREATE INDEX IF NOT EXISTS idx_college_key ON alumni (college_key);

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
